// Nursing Assisting Practice Test 2. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items, with different care situations from Practice Test 1.
import {q, mix} from './q.js';
const DUG='Dugan, Nursing Assisting: A Foundation in Caregiving', ROE='Roe, The Nursing Assistant: Essentials of Holistic Care';
const ROLE='Nursing Assistant Roles and Responsibilities', AP='Anatomy and Physiology', INF='Infection Control/Safety', COMM='Communication/Culture', CARE='Providing and Reporting Care', DIS='Disabilities and Disorders';

export default {
 id:'nursing-assisting-2',
 event:'Nursing Assisting',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Dugan’s Nursing Assisting: A Foundation in Caregiving and Roe’s The Nursing Assistant',
 plan:[{area:ROLE,weight:6},{area:AP,weight:20},{area:INF,weight:14},{area:COMM,weight:10},{area:CARE,weight:30},{area:DIS,weight:20}],
 questions:mix([
  q(ROLE,'Which document lists the rights of residents in long-term care facilities, as required by OBRA?','The Residents’ Bill of Rights',['The facility’s fire plan','The nurse practice act','The daily assignment sheet'],'B','Rights include privacy, dignity, making choices, voicing complaints and managing personal funds.',DUG),
  q(ROLE,'A resident offers a nursing assistant $20 for extra help. What should the assistant do?','Politely refuse the money',['Accept it and share it with staff','Accept it if no one sees','Ask the family to pay instead'],'D','Accepting gifts or money is unprofessional and may be seen as exploiting the resident.',DUG),
  q(ROLE,'Who is responsible for supervising the work of a nursing assistant?','A licensed nurse',['The resident’s family','The dietary manager','Another nursing assistant'],'A','Nurses delegate tasks based on the assistant’s training, state rules and the resident’s condition.',DUG),
  q(AP,'Which muscle is the main muscle of breathing?','Diaphragm',['Biceps','Deltoid','Trapezius'],'C','The diaphragm contracts and flattens during inhalation, drawing air into the lungs.',DUG),
  q(AP,'Which body system includes the thyroid, adrenal and pituitary glands?','Endocrine',['Lymphatic','Integumentary','Nervous'],'B','Endocrine glands release hormones into the blood to regulate body functions.',DUG),
  q(AP,'Which blood vessels carry blood away from the heart?','Arteries',['Veins','Venules','Lymph vessels'],'D','Most arteries carry oxygen-rich blood. Veins return blood to the heart.',DUG),
  q(AP,'What is the largest organ of the body?','Skin',['Liver','Brain','Lungs'],'A','The skin protects the body, regulates temperature and senses touch, pain and pressure.',DUG),
  q(AP,'Which part of the brain controls balance and coordination?','Cerebellum',['Cerebrum','Medulla','Hypothalamus'],'C','The cerebrum controls thinking and voluntary movement; the medulla controls breathing and heart rate.',DUG),
  q(AP,'Where does most digestion and absorption of food occur?','Small intestine',['Stomach','Large intestine','Esophagus'],'B','Villi in the small intestine absorb nutrients. The large intestine mainly absorbs water and forms stool.',DUG),
  q(AP,'Which change in the skin with aging increases the risk of tears and pressure injuries?','Thinner, drier skin',['Thicker, oilier skin','More fat beneath the skin','Faster cell renewal'],'D','Gentle handling, lifting sheets and moisturizers protect fragile older skin.',DUG),
  q(AP,'What is the function of the urinary bladder?','Store urine',['Filter blood','Make hormones','Absorb nutrients'],'A','The kidneys filter blood to make urine, which flows through the ureters to the bladder.',DUG),
  q(AP,'Which sense organ contains the cochlea?','Ear',['Eye','Nose','Tongue'],'C','The cochlea in the inner ear changes sound vibrations into nerve signals.',DUG),
  q(AP,'Which hormone lowers blood sugar?','Insulin',['Glucagon','Adrenaline','Cortisol'],'B','Insulin moves glucose into cells. Glucagon, adrenaline and cortisol raise blood sugar.',DUG),
  q(INF,'Which is an example of a portal of exit in the chain of infection?','A cough or sneeze',['Clean, intact skin','A sterile dressing','Hand sanitizer'],'D','Breaking any link—such as covering coughs—stops the spread of infection.',DUG),
  q(INF,'How long should hands be rubbed together with soap during handwashing?','At least 20 seconds',['About 5 seconds','About 10 seconds','2 full minutes'],'A','Clean between the fingers, under the nails and the wrists, then rinse with fingertips down.',DUG),
  q(INF,'Which precautions are used for a resident with influenza?','Droplet precautions',['Airborne precautions','Contact only','No precautions'],'C','Wear a mask within about 6 feet of the resident. Airborne precautions are for TB, measles and chickenpox.',DUG),
  q(INF,'Which item of PPE is removed first?','Gloves',['Gown','Mask','Goggles'],'B','Gloves are most contaminated. The usual order is gloves, goggles, gown, then mask, followed by hand hygiene.',DUG),
  q(INF,'What does the acronym PASS describe?','How to use a fire extinguisher',['How to lift a resident safely','How to respond to a fall','How to handle a spill'],'D','Pull the pin, Aim at the base, Squeeze the handle and Sweep side to side.',DUG),
  q(INF,'A resident is found on the floor. What should the nursing assistant do first?','Call for help and stay',['Lift the resident into bed','Leave to find the nurse','Have the resident stand'],'A','Do not move the resident until the nurse checks for injuries.',DUG),
  q(INF,'What should be done with soiled linen?','Hold it away from your uniform',['Shake it out before bagging','Place it on the floor','Carry it against your chest'],'C','Shaking linen spreads microorganisms. Place soiled linen in a laundry bag or hamper.',DUG),
  q(COMM,'What is the best way to communicate with a resident who has a visual impairment?','Identify yourself when entering',['Shout so they can hear','Move their belongings often','Avoid speaking to them'],'B','Explain what you are doing, use the clock method for food and keep items in the same place.',DUG),
  q(COMM,'A resident speaks a different language. What is the best approach?','Use an interpreter or picture cards',['Speak louder in English','Ask a child to translate','Avoid talking to the resident'],'D','Family members and children may not translate medical terms accurately and may compromise privacy.',DUG),
  q(COMM,'Which is an example of nonverbal communication?','Facial expressions',['A written report','A phone call','A spoken greeting'],'A','Body language, touch, tone and gestures often send stronger messages than words.',DUG),
  q(COMM,'A resident is angry and yelling. Which response is best?','Stay calm and listen',['Yell back to be heard','Leave the resident alone','Argue about the facts'],'C','Do not take it personally. Report the behavior and ensure safety if it escalates.',DUG),
  q(COMM,'Which statement is objective information that should be reported?','Blood pressure is 160/96',['The resident seems sad','The resident feels nauseated','The resident says she hurts'],'B','Objective data can be seen, measured or heard. Subjective data are what the resident reports.',DUG),
  q(CARE,'What is the normal range for an adult oral temperature?','97.6 °F to 99.6 °F',['95 °F to 96 °F','100.4 °F to 102 °F','90 °F to 94 °F'],'D','Rectal temperatures are about 1 °F higher and axillary about 1 °F lower than oral.',DUG),
  q(CARE,'What is the normal respiratory rate for an adult?','12–20 per minute',['4–8 per minute','25–35 per minute','40–50 per minute'],'A','Count for a full minute if the rate is irregular, and note depth and rhythm.',DUG),
  q(CARE,'Where is the radial pulse taken?','Thumb side of the wrist',['Inside of the elbow','Side of the neck','Behind the knee'],'C','The brachial pulse is at the elbow, the carotid at the neck and the popliteal behind the knee.',DUG),
  q(CARE,'Which systolic blood pressure is considered high and should be reported?','150 mm Hg',['110 mm Hg','118 mm Hg','100 mm Hg'],'B','A systolic pressure of 130 or higher is considered high in adults. Report readings outside the resident’s usual range.',DUG),
  q(CARE,'How many mL are in a 6-oz cup of coffee?','180 mL',['60 mL','120 mL','240 mL'],'D','1 oz = 30 mL, so 6 × 30 = 180 mL. Record intake and output accurately.',DUG),
  q(CARE,'In which position is the resident lying on the left side with the right knee drawn up?','Sims position',['Supine position','Prone position','Fowler position'],'A','Sims position is a left side-lying position used for enemas and rectal procedures.',DUG),
  q(CARE,'What is the correct way to give oral care to an unconscious resident?','Turn the head to the side; use little liquid',['Flood the mouth with water','Place fingers between the teeth','Do it with the resident flat on the back'],'C','Positioning and a small amount of liquid prevent aspiration. Use a padded tongue blade to keep the mouth open.',DUG),
  q(CARE,'When transferring a resident, why should the nursing assistant keep the resident close to the body?','It protects the assistant’s back',['It makes the resident heavier','It speeds the transfer only','It is required for privacy'],'B','A wide base of support, bent knees and avoiding twisting also prevent back injury.',DUG),
  q(CARE,'What is the purpose of a gait belt?','Gives a secure grip during transfers',['Restrains a confused resident','Holds a urinary bag','Keeps the resident’s gown closed'],'D','The belt is placed over clothing at the waist. It is not a restraint.',DUG),
  q(CARE,'Which observation about a resident’s urine should be reported?','Cloudy, foul-smelling urine',['Pale yellow, clear urine','About 1500 mL in a day','No odor'],'A','Cloudy, foul-smelling or bloody urine may indicate infection or other problems.',DUG),
  q(CARE,'How should bed linens be applied to prevent pressure injuries?','Tight and free of wrinkles',['Loose and bunched','Folded under the resident','With extra layers of pads'],'C','Wrinkles and extra layers increase pressure and friction on the skin.',DUG),
  q(CARE,'Which action promotes a resident’s dignity during bathing?','Keep the resident covered when possible',['Leave the door open','Bathe two residents at once','Talk about the resident with coworkers'],'B','Pull curtains, close doors and expose only the area being washed.',DUG),
  q(CARE,'When feeding a resident, what is the best practice?','Offer small bites slowly',['Rush to finish within 5 minutes','Mix all foods together','Stand above the resident'],'D','Sit at eye level, describe the food and give the resident time to chew and swallow.',DUG),
  q(CARE,'What is the correct way to measure a resident’s height in bed?','Measure from head to heel',['Estimate it just by looking','Ask a family member','Measure only the legs'],'A','Make a mark at the top of the head and the bottom of the heel with the resident lying straight.',DUG),
  q(CARE,'Why should a resident with a urinary catheter receive perineal care daily?','It reduces infection risk',['It stops urine production','It removes the catheter','It increases bladder size'],'C','Clean the catheter tubing from the meatus outward, about 4 inches, without pulling on it.',DUG),
  q(DIS,'A resident with dementia becomes agitated in the late afternoon. What is this called?','Sundowning',['Wandering','Perseveration','Catastrophic reaction'],'B','Keep a calm environment, a routine and good lighting. Report changes in behavior.',DUG),
  q(DIS,'Which is a sign of a urinary tract infection in an older adult?','New confusion',['Increased appetite','Better sleep','Clear urine'],'D','Older adults may not have fever or pain; sudden confusion is often the first sign.',DUG),
  q(DIS,'A resident with diabetes has a sore on the foot. Why is this a concern?','It heals slowly and infects easily',['Diabetes makes sores heal faster','It only affects the hands','It is never serious'],'A','Poor circulation and nerve damage raise the risk of ulcers and amputation. Report foot problems.',DUG),
  q(DIS,'Which finding should be reported in a resident with heart failure?','Ankle swelling',['Normal appetite','Steady weight','Clear lung sounds'],'C','Edema and weight gain may mean fluid buildup. Shortness of breath when lying flat is also important.',DUG),
  q(DIS,'What is a common symptom of multiple sclerosis?','Fatigue and blurred vision',['Frequent bone fractures','Very high blood sugar','A spreading skin rash'],'B','MS damages the myelin of nerves, causing weakness, numbness, vision changes and fatigue.',DUG),
  q(DIS,'How can a nursing assistant help a resident with arthritis?','Encourage gentle range of motion',['Keep the joints still all day','Apply ice for hours','Limit all walking'],'D','Gentle movement keeps joints flexible. Warm baths may ease morning stiffness.',DUG),
  q(DIS,'A resident with COPD should be positioned how to make breathing easier?','Sitting up and leaning forward',['Lying flat on the back','Lying face down','With the feet raised high'],'A','Orthopneic positioning helps the lungs expand. Pursed-lip breathing also helps.',DUG),
  q(DIS,'Which is an early sign of Alzheimer disease?','Forgetting recent events',['Losing all speech','Inability to walk','Difficulty swallowing'],'C','Later stages include losing speech, mobility and the ability to swallow.',DUG),
  q(DIS,'Which care measure helps a resident with a below-knee amputation?','Monitor the stump skin for breakdown',['Keep the stump in a dependent position','Avoid exercise of the leg','Ignore phantom pain'],'B','Phantom pain is real and should be reported. Positioning prevents contractures.',DUG),
  q(DIS,'A resident is receiving hospice care. What is the main goal?','Comfort and quality of life',['Curing the disease','Aggressive treatment','Avoiding all medicines'],'D','Hospice provides pain control and emotional support for the resident and family.',DUG)
 ],907)
};
